package com.overlay.audio.plugins

import org.json.JSONArray
import org.json.JSONObject
import java.io.File
import kotlin.math.PI
import kotlin.math.abs
import kotlin.math.round
import kotlin.math.sin
import kotlin.test.Test
import kotlin.test.assertEquals
import kotlin.test.assertNotNull
import kotlin.test.assertTrue

/**
 * Golden-vector parity for the studio FX suite.
 *
 * The fixture is generated by this Kotlin engine and consumed by the
 * TypeScript implementation in NCSoundLab. A change to any module formula
 * changes the vectors, so a deliberate DSP change must regenerate the file
 * (`-Daudio.fx.emit=true`) and update the TS port in the same commit. That is
 * the mechanism behind "the same rack sounds the same in every app".
 */
class FxParityFixtureTest {

    private val sr = 48_000f
    private val frames = 1024
    private val fixtureDir = File(System.getProperty("audio.fx.fixtures", "../audio-fx"))
    private val fixtureFile = File(fixtureDir, "parity-fixtures.json")
    private val emit = System.getProperty("audio.fx.emit") == "true"

    @Test
    fun `kotlin engine matches the committed parity fixture`() {
        val input = deterministicInput(frames, sr)
        val cases = buildCases()
        val rendered = cases.map { (name, chain) ->
            name to FxOfflineRenderer.renderMono(input, sr, chain)
        }

        if (emit) {
            fixtureDir.mkdirs()
            val root = JSONObject()
            root.put("schema", FIXTURE_SCHEMA)
            root.put("sampleRate", sr.toDouble())
            root.put("frames", frames)
            root.put("input", quantized(input, 6))
            val array = JSONArray()
            for ((index, entry) in rendered.withIndex()) {
                val node = JSONObject()
                node.put("name", entry.first)
                node.put("chain", FxChainCodec.encode(cases[index].second))
                node.put("output", quantized(entry.second, 6))
                array.put(node)
            }
            root.put("cases", array)
            fixtureFile.writeText(root.toString())
            File(fixtureDir, "catalog.json").writeText(FxChainCodec.catalogJson())
            println("wrote ${fixtureFile.absolutePath} (${fixtureFile.length()} bytes) + catalog.json")
            return
        }

        assertTrue(fixtureFile.exists(), "missing parity fixture: ${fixtureFile.absolutePath}")
        val root = JSONObject(fixtureFile.readText())
        assertEquals(FIXTURE_SCHEMA, root.getString("schema"))
        assertEquals(frames, root.getInt("frames"))
        val storedInput = root.getJSONArray("input")
        assertEquals(input.size, storedInput.length())
        for (i in input.indices) {
            assertEquals(input[i], storedInput.getDouble(i).toFloat(), 1e-6f, "input sample $i")
        }
        val storedCases = root.getJSONArray("cases")
        assertEquals(rendered.size, storedCases.length())
        for (i in rendered.indices) {
            val node = storedCases.getJSONObject(i)
            assertEquals(rendered[i].first, node.getString("name"))
            val expected = node.getJSONArray("output")
            assertEquals(rendered[i].second.size, expected.length(), node.getString("name"))
            var maxDiff = 0f
            for (s in rendered[i].second.indices) {
                val diff = abs(rendered[i].second[s] - expected.getDouble(s).toFloat())
                if (diff > maxDiff) maxDiff = diff
            }
            assertTrue(
                maxDiff <= 2e-6f,
                "${node.getString("name")} drifted by $maxDiff; regenerate the fixture only for an intentional DSP change",
            )
        }
    }

    /**
     * One case per module (defaults) plus a realistic four-module vocal chain.
     * Defaults exercise every parameter path except choices that default to
     * their first position; the chain covers ordering and state carry-over.
     */
    private fun buildCases(): List<Pair<String, PluginChain>> {
        // The TS port in NCSoundLab has not implemented these newer vocal
        // modules yet. They are covered by the app-level DSP tests; keep them
        // out of the cross-language fixture until the port catches up, instead
        // of regenerating vectors the other engine cannot reproduce.
        val pendingTsPort = setOf(PluginKind.VOCAL_RIDER, PluginKind.RESONANCE_SMOOTHER)
        val cases = PluginKind.entries
            .filterNot { it in pendingTsPort }
            .map { kind ->
                kind.name to PluginChain(listOf(PluginCatalog.defaultSlot(kind)))
            }
            .toMutableList()
        cases += "CHAIN_NEVE_1176_TAPE_PLATE" to PluginChain(
            listOf(
                PluginCatalog.defaultSlot(PluginKind.NEVE_1073).withParam("driveDb", 6f).withParam("hpfHz", 80f),
                PluginCatalog.defaultSlot(PluginKind.FET_1176).withParam("inputDb", 8f).withParam("ratio", 8f),
                PluginCatalog.defaultSlot(PluginKind.TAPE_MACHINE).withParam("driveDb", 3f).withParam("speedIps", 15f),
                PluginCatalog.defaultSlot(PluginKind.PLATE_REVERB).withParam("mix", 0.3f),
            ),
        )
        return cases
    }

    private fun deterministicInput(frames: Int, sampleRate: Float): FloatArray {
        var state = 0x1234567
        fun next(): Float {
            state = state * 1664525 + 1013904223
            val u = (state ushr 8) and 0xFFFFFF
            return u / 16777216f - 0.5f
        }
        val out = FloatArray(frames)
        for (i in 0 until frames) {
            val tone = 0.4 * sin(2.0 * PI * 220.0 * i / sampleRate)
            val noise = 0.2f * next()
            out[i] = quantize((tone + noise).toFloat(), 6)
        }
        return out
    }

    private fun quantize(value: Float, decimals: Int): Float {
        val scale = Math.pow(10.0, decimals.toDouble()).toFloat()
        return round(value * scale) / scale
    }

    private fun quantized(values: FloatArray, decimals: Int): JSONArray {
        val array = JSONArray()
        for (v in values) array.put(quantize(v, decimals).toDouble())
        return array
    }

    companion object {
        const val FIXTURE_SCHEMA = "nc.studiofx.parity.v1"
    }
}
